ation, no automatic save rollback; assemblies remain loaded."",""validation"":{""status"":""not_recorded"",""record"":null,""currentSourceVerified"":false},""sourceSha256"":""651007c2619fae74c3759ddf94ebec2f3af57394a85b45ff7d928f8dccdada6c"",""source"":""using System;\nusing ModDevBridge;\n\n// Optional probe adapter. Prefer the direct reload_mod MCP tool.\npublic sealed class NativeModReloader : IStructuredDevModule\n{\n    public string Start() => \""Ready; use MOD_ID|unique.dll, or call reload_mod directly\"";\n    public object ExecuteStructured(string command)\n    {\n        var parts = command.Split('|');\n        if (parts.Length != 2) throw new ArgumentException(\""Expected MOD_ID|unique.dll\"");\n        return NativeModReload.Execute(parts[0], parts[1]);\n    }\n    public string Execute(string command) => throw new InvalidOperationException(\""Use structured execution\"");\n    public void Stop() { }\n}\n""}]");
